@startuml

class Driver {
  + ID : int
  + Name : string
  + IsOnSickLeave : boolean
}

class Bus {
  + LicensePlate : string
  + IsInRepairShop : boolean
}

class Route {
  + RouteNumber : int
}

class Shift {
  + ShiftType : ShiftType
}

class Schedule {
  + Date : date
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class CityStaff {}

CityStaff "1" -- "*" Driver : manages
CityStaff "1" -- "*" Bus : manages
CityStaff "1" -- "*" Route : manages
CityStaff "1" -- "*" Schedule : manages

Route "1" -- "*" Bus : assignedTo
Bus "1" -- "*" Route : serves

Schedule "1" -- "1..*" Shift : contains
Schedule "1" -- "1" Route : forRoute
Schedule "1" -- "1" Bus : forBus
Schedule "1" -- "1..*" Driver : forDriver

Driver "1" -- "*" Shift : assignedTo
Bus "1" -- "*" Shift : assignedTo

@enduml

